import React, { useState, useEffect, useRef } from 'react';
import { 
  Bot, 
  LayoutDashboard, 
  Settings, 
  Smartphone, 
  Calendar, 
  MessageSquareWarning, 
  Code2, 
  Sparkles, 
  Activity, 
  Menu, 
  X,
  Home,
  Bell,
  BellOff,
  CreditCard,
  AlertCircle
} from 'lucide-react';

// Components
import DashboardOverview from './components/DashboardOverview';
import ClientConfigurator from './components/ClientConfigurator';
import SandboxSimulator from './components/SandboxSimulator';
import BookingsManager from './components/BookingsManager';
import ComplaintsDesk from './components/ComplaintsDesk';
import IntegrationHub from './components/IntegrationHub';
import PricingManager from './components/PricingManager';

// Types
import { BusinessConfig, Booking, Complaint, WebhookLog } from './types';

export default function App() {
  const [tab, setTab] = useState<string>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState<boolean>(false);
  const [isResetting, setIsResetting] = useState<boolean>(false);

  // User state
  const [currentUser, setCurrentUser] = useState<any>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('sanad_user');
      return stored ? JSON.parse(stored) : null;
    }
    return null;
  });

  const [paymentRequests, setPaymentRequests] = useState<any[]>([]);

  // Auth form states
  const [authTab, setAuthTab] = useState<'login' | 'register'>('login');
  const [authError, setAuthError] = useState<string>('');
  const [authLoading, setAuthLoading] = useState<boolean>(false);

  // Login fields
  const [loginUsername, setLoginUsername] = useState<string>('');
  const [loginPassword, setLoginPassword] = useState<string>('');

  // Register fields
  const [regName, setRegName] = useState<string>('');
  const [regUsername, setRegUsername] = useState<string>('');
  const [regPassword, setRegPassword] = useState<string>('');
  const [regBusinessName, setRegBusinessName] = useState<string>('');
  const [regBusinessType, setRegBusinessType] = useState<string>('clinic');

  // Core synchronized data states
  const [businesses, setBusinesses] = useState<BusinessConfig[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [complaints, setComplaints] = useState<Complaint[]>([]);
  const [webhookLogs, setWebhookLogs] = useState<WebhookLog[]>([]);

  // Refs to track previous records for change detection
  const prevBookingsRef = useRef<string[]>([]);
  const prevComplaintsRef = useRef<string[]>([]);
  const isFirstLoadRef = useRef<boolean>(true);

  // Browser Notification state
  const [notificationPermission, setNotificationPermission] = useState<string>('default');

  useEffect(() => {
    if (typeof window !== 'undefined' && 'Notification' in window) {
      setNotificationPermission(Notification.permission);
    }
  }, []);

  const requestNotificationPermission = async () => {
    if (typeof window === 'undefined' || !('Notification' in window)) {
      alert("متصفحك الحالي لا يدعم إشعارات الويب.");
      return;
    }
    try {
      const permission = await Notification.requestPermission();
      setNotificationPermission(permission);
      if (permission === 'granted') {
        new Notification("سند AI", {
          body: "تم تفعيل التنبيهات الذكية للوكالة بنجاح! 🔔",
          dir: "rtl"
        });
        playNotificationBeep();
      }
    } catch (err) {
      console.error("Error requesting notification permission:", err);
    }
  };

  const playNotificationBeep = () => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(587.33, audioCtx.currentTime); // D5 note
      gainNode.gain.setValueAtTime(0.12, audioCtx.currentTime);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.15);
    } catch (e) {
      console.warn("Audio Context beep was blocked or failed", e);
    }
  };

  const triggerBrowserNotification = (title: string, body: string) => {
    if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted') {
      try {
        new Notification(title, {
          body: body,
          dir: "rtl"
        });
        playNotificationBeep();
      } catch (e) {
        console.error("Error displaying notification:", e);
      }
    }
  };

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthLoading(true);
    setAuthError('');
    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: loginUsername, password: loginPassword })
      });
      const data = await response.json();
      if (response.ok && data.success) {
        localStorage.setItem('sanad_user', JSON.stringify(data.user));
        setCurrentUser(data.user);
        setBusinesses([]);
        setBookings([]);
        setComplaints([]);
        setWebhookLogs([]);
        setPaymentRequests([]);
        setLoginUsername('');
        setLoginPassword('');
      } else {
        setAuthError(data.error || 'اسم المستخدم أو كلمة المرور غير صحيحة');
      }
    } catch (err) {
      setAuthError('تعذر الاتصال بالخادم الرئيسي.');
    } finally {
      setAuthLoading(false);
    }
  };

  const handleRegisterSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthLoading(true);
    setAuthError('');
    try {
      const response = await fetch('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: regName,
          username: regUsername,
          password: regPassword,
          businessName: regBusinessName,
          businessType: regBusinessType
        })
      });
      const data = await response.json();
      if (response.ok && data.success) {
        localStorage.setItem('sanad_user', JSON.stringify(data.user));
        setCurrentUser(data.user);
        setBusinesses([]);
        setBookings([]);
        setComplaints([]);
        setWebhookLogs([]);
        setPaymentRequests([]);
        setRegName('');
        setRegUsername('');
        setRegPassword('');
        setRegBusinessName('');
      } else {
        setAuthError(data.error || 'فشلت عملية إنشاء الحساب');
      }
    } catch (err) {
      setAuthError('تعذر الاتصال بالخادم الرئيسي.');
    } finally {
      setAuthLoading(false);
    }
  };

  // Fetch all state records from Express backend
  const fetchState = async (user = currentUser) => {
    if (!user) return;
    try {
      const query = `?role=${user.role}&businessId=${user.businessId || ''}`;
      const response = await fetch(`/api/state${query}`);
      const data = await response.json();

      const newBookings: Booking[] = data.bookings || [];
      const newComplaints: Complaint[] = data.complaints || [];

      // Detect changes if this is not the first load of the page
      if (!isFirstLoadRef.current) {
        // Look for newly added pending bookings
        newBookings.forEach(booking => {
          if (!prevBookingsRef.current.includes(booking.id) && booking.status === 'pending') {
            const bizName = (data.businesses || []).find((b: BusinessConfig) => b.id === booking.businessId)?.name || 'المنشأة';
            triggerBrowserNotification(
              "📅 طلب حجز جديد معلق!",
              `العميل: ${booking.customerName} يود حجز خدمة (${booking.service}) في ${bizName}`
            );
          }
        });

        // Look for newly added complaints
        newComplaints.forEach(complaint => {
          if (!prevComplaintsRef.current.includes(complaint.id)) {
            const cat = complaint.category || 'عام';
            triggerBrowserNotification(
              "⚠️ شكوى عميل جديدة واردة!",
              `العميل: ${complaint.customerName} - تصنيف: ${cat}. مضمونها: ${complaint.summary}`
            );
          }
        });
      }

      // Keep references updated
      prevBookingsRef.current = newBookings.map(b => b.id);
      prevComplaintsRef.current = newComplaints.map(c => c.id);
      isFirstLoadRef.current = false;

      let fetchedBusinesses = data.businesses || [];
      // تصفية المنشآت للمشترك بحيث لا يرى سوى المنشأة التي سجل بها فقط
      if (user.role !== 'owner' && user.businessId) {
        fetchedBusinesses = fetchedBusinesses.filter((b: BusinessConfig) => b.id === user.businessId);
      }
      setBusinesses(fetchedBusinesses);
      setBookings(newBookings);
      setComplaints(newComplaints);
      setWebhookLogs(data.webhookLogs || []);
      setPaymentRequests(data.paymentRequests || []);
    } catch (error) {
      console.error("Error fetching agency state:", error);
    }
  };

  useEffect(() => {
    fetchState();

    // Set up real-time background polling every 5 seconds to notify immediately
    const interval = setInterval(() => {
      fetchState();
    }, 5000);

    return () => clearInterval(interval);
  }, [currentUser]); // Fetch state polling depends only on currentUser now

  // Update business handler
  const handleUpdateBusiness = async (updated: BusinessConfig): Promise<boolean> => {
    try {
      const response = await fetch('/api/business/update', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updated)
      });
      const result = await response.json();
      if (result.success) {
        setBusinesses(prev => prev.map(b => b.id === updated.id ? result.business : b));
        fetchState(); // sync logs
        return true;
      }
    } catch (err) {
      console.error("Error updating business config:", err);
    }
    return false;
  };

  // Handle update subscriber plan & subscription details
  const handleUpdateSubscription = async (
    id: string, 
    plan?: string, 
    status?: string, 
    expiry?: string, 
    limit?: number, 
    resetUsage?: boolean
  ): Promise<boolean> => {
    try {
      const response = await fetch('/api/business/subscription/update', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          id, 
          subscriptionPlan: plan, 
          subscriptionStatus: status, 
          subscriptionExpiry: expiry, 
          aiResponseLimit: limit, 
          resetUsage 
        })
      });
      const result = await response.json();
      if (result.success) {
        fetchState();
        return true;
      }
    } catch (err) {
      console.error("Error updating subscription:", err);
    }
    return false;
  };

  // Manage booking status or manual creation handler
  const handleManageBooking = async (
    id: string, 
    action: 'confirm' | 'cancel' | 'complete' | 'create', 
    updates?: any
  ): Promise<boolean> => {
    try {
      const response = await fetch('/api/bookings/manage', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, action, ...updates })
      });
      const result = await response.json();
      if (result.success) {
        fetchState();
        return true;
      }
    } catch (err) {
      console.error("Error managing booking:", err);
    }
    return false;
  };

  // Manage complaints or manual creation handler
  const handleManageComplaint = async (
    id: string, 
    action: 'resolve' | 'review' | 'update', 
    updates?: any
  ): Promise<boolean> => {
    try {
      const response = await fetch('/api/complaints/manage', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, action, ...updates })
      });
      const result = await response.json();
      if (result.success) {
        fetchState();
        return true;
      }
    } catch (err) {
      console.error("Error managing complaint:", err);
    }
    return false;
  };

  // Sandbox simulation event triggers
  const handleTriggerSimulation = async (
    businessId: string, 
    message: string, 
    channel: 'whatsapp' | 'instagram',
    senderName: string,
    senderPhone: string
  ) => {
    const response = await fetch('/api/simulate-chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ businessId, message, channel, senderName, senderPhone })
    });
    return response.json();
  };

  // Reset database state to defaults
  const handleResetData = async () => {
    setIsResetting(true);
    try {
      const response = await fetch('/api/reset', { method: 'POST' });
      const result = await response.json();
      if (result.success) {
        setBookings(result.bookings);
        setComplaints(result.complaints);
        setWebhookLogs(result.webhookLogs);
      }
    } catch (err) {
      console.error("Error resetting states:", err);
    } finally {
      setIsResetting(false);
    }
  };

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center p-4 font-sans" dir="rtl">
        <div className="w-full max-w-md bg-gradient-to-b from-slate-900 to-slate-950 rounded-2xl border border-slate-850 p-6 md:p-8 shadow-2xl relative overflow-hidden space-y-6">

          {/* Decorative Glow */}
          <div className="absolute -top-12 -left-12 w-24 h-24 bg-emerald-500/10 rounded-full blur-2xl pointer-events-none" />
          <div className="absolute -bottom-12 -right-12 w-24 h-24 bg-emerald-500/10 rounded-full blur-2xl pointer-events-none" />

          {/* Logo / Header */}
          <div className="flex flex-col items-center text-center gap-3">
            <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center shadow-lg shadow-emerald-500/20 text-slate-950">
              <Bot className="w-7 h-7 stroke-[2.5]" />
            </div>
            <div>
              <h1 className="text-xl font-black text-white">منصة سند AI</h1>
              <p className="text-xs text-slate-400 mt-1">وكالة الذكاء الاصطناعي الشاملة لأتمتة أعمال المشتركين</p>
            </div>
          </div>

          {/* Tabs for Login vs Register */}
          <div className="flex bg-slate-950 p-1 rounded-xl border border-slate-850">
            <button
              onClick={() => { setAuthTab('login'); setAuthError(''); }}
              className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all cursor-pointer text-center ${
                authTab === 'login' ? 'bg-emerald-500 text-slate-950 font-black' : 'text-slate-400 hover:text-slate-300'
              }`}
            >
              تسجيل الدخول
            </button>
            <button
              onClick={() => { setAuthTab('register'); setAuthError(''); }}
              className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all cursor-pointer text-center ${
                authTab === 'register' ? 'bg-emerald-500 text-slate-950 font-black' : 'text-slate-400 hover:text-slate-300'
              }`}
            >
              إنشاء حساب مشرف
            </button>
          </div>

          {authError && (
            <div className="bg-rose-950/40 border border-rose-900/50 p-3 rounded-xl text-xs text-rose-400 font-medium flex items-center gap-2">
              <AlertCircle className="w-4 h-4 shrink-0 text-rose-500" />
              <span>{authError}</span>
            </div>
          )}

          {authTab === 'login' ? (
            <form onSubmit={handleLoginSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-400">اسم المستخدم أو البريد الإلكتروني</label>
                <input
                  type="text"
                  required
                  placeholder="name@example.com"
                  value={loginUsername}
                  onChange={(e) => setLoginUsername(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3.5 py-2.5 text-xs text-white outline-none focus:border-emerald-500 transition-colors"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-400">كلمة المرور</label>
                <input
                  type="password"
                  required
                  placeholder="••••••••"
                  value={loginPassword}
                  onChange={(e) => setLoginPassword(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3.5 py-2.5 text-xs text-white outline-none focus:border-emerald-500 transition-colors"
                />
              </div>

              <button
                type="submit"
                disabled={authLoading}
                className="w-full py-2.5 bg-emerald-500 hover:bg-emerald-600 disabled:opacity-50 text-slate-950 font-black rounded-xl text-xs transition-all shadow-lg shadow-emerald-500/10 cursor-pointer flex items-center justify-center gap-2 mt-2"
              >
                {authLoading ? 'جاري التحقق...' : 'تسجيل الدخول'}
              </button>

            </form>
          ) : (
            <form onSubmit={handleRegisterSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-400">الاسم الكامل</label>
                <input
                  type="text"
                  required
                  placeholder="الاسم الثنائي أو الثلاثي"
                  value={regName}
                  onChange={(e) => setRegName(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3.5 py-2.5 text-xs text-white outline-none focus:border-emerald-500 transition-colors"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-400">البريد الإلكتروني</label>
                <input
                  type="email"
                  required
                  placeholder="name@example.com"
                  value={regUsername}
                  onChange={(e) => setRegUsername(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3.5 py-2.5 text-xs text-white outline-none focus:border-emerald-500 transition-colors"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-400">كلمة المرور</label>
                <input
                  type="password"
                  required
                  placeholder="••••••••"
                  value={regPassword}
                  onChange={(e) => setRegPassword(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3.5 py-2.5 text-xs text-white outline-none focus:border-emerald-500 transition-colors"
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400">اسم المنشأة / النشاط</label>
                  <input
                    type="text"
                    required
                    placeholder="عيادة النور، مطعم دمشق..."
                    value={regBusinessName}
                    onChange={(e) => setRegBusinessName(e.target.value)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3.5 py-2.5 text-xs text-white outline-none focus:border-emerald-500 transition-colors"
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-400">نوع النشاط</label>
                  <select
                    value={regBusinessType}
                    onChange={(e) => setRegBusinessType(e.target.value)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-3 py-2.5 text-xs text-white outline-none focus:border-emerald-500 transition-colors"
                  >
                    <option value="clinic">عيادة طبية</option>
                    <option value="restaurant">مطعم</option>
                    <option value="cafe">مقهى</option>
                    <option value="service">شركة خدمات عامة / أخرى</option>
                  </select>
                </div>
              </div>

              <button
                type="submit"
                disabled={authLoading}
                className="w-full py-2.5 bg-emerald-500 hover:bg-emerald-600 disabled:opacity-50 text-slate-950 font-black rounded-xl text-xs transition-all shadow-lg shadow-emerald-500/10 cursor-pointer flex items-center justify-center gap-2 mt-2"
              >
                {authLoading ? 'جاري التأسيس...' : 'إنشاء حساب وتأسيس منشأة 🚀'}
              </button>
            </form>
          )}

        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans" dir="rtl">

      {/* Top Header Navigation Bar */}
      <header className="sticky top-0 z-40 bg-slate-950/85 backdrop-blur-md border-b border-slate-900 px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setSidebarOpen(!sidebarOpen)}
            className="p-2 bg-slate-900 hover:bg-slate-800 rounded-lg lg:hidden transition-colors cursor-pointer"
          >
            {sidebarOpen ? <X className="w-5 h-5 text-white" /> : <Menu className="w-5 h-5 text-white" />}
          </button>

          <div 
            onClick={() => setTab('dashboard')}
            className="flex items-center gap-2.5 cursor-pointer hover:opacity-90 active:scale-[0.98] transition-all group"
            title="العودة للرئيسية"
          >
            <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-500/20 text-slate-950 group-hover:scale-105 transition-transform">
              <Bot className="w-5.5 h-5.5 stroke-[2.5]" />
            </div>
            <div>
              <div className="flex items-center gap-1.5">
                <span className="text-base font-bold tracking-tight text-white font-sans group-hover:text-emerald-400 transition-colors">سند AI</span>
                <span className="text-[10px] bg-slate-800 text-emerald-400 px-1.5 py-0.5 rounded-md font-bold font-mono">Agency Core v3.5</span>
              </div>
              <p className="text-[10px] text-slate-500 font-sans hidden sm:block">وكالة الذكاء الاصطناعي الشاملة لأتمتة أعمال المشتركين</p>
            </div>
          </div>
        </div>

        {/* Top Header Indicators */}
        <div className="flex items-center gap-4">
          {tab !== 'dashboard' && (
            <button
              onClick={() => setTab('dashboard')}
              className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-bold px-3 py-1.5 rounded-xl text-xs transition-all active:scale-95 cursor-pointer shadow-lg shadow-emerald-500/15"
            >
              <Home className="w-3.5 h-3.5" />
              <span>الرئيسية</span>
            </button>
          )}

          {/* Browser Notifications Request Toggle */}
          <button
            onClick={requestNotificationPermission}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all active:scale-95 cursor-pointer border ${
              notificationPermission === 'granted'
                ? 'bg-slate-900 text-emerald-400 border-emerald-950/80 hover:bg-slate-850'
                : notificationPermission === 'denied'
                ? 'bg-rose-950/30 text-rose-400 border-rose-900/40 hover:bg-rose-950/50'
                : 'bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-extrabold shadow-lg shadow-emerald-500/10'
            }`}
            title={
              notificationPermission === 'granted'
                ? 'تنبيهات المتصفح مفعلة بنجاح'
                : notificationPermission === 'denied'
                ? 'تنبيهات المتصفح محظورة من الإعدادات'
                : 'اضغط هنا لتفعيل إشعارات المتصفح الفورية'
            }
          >
            {notificationPermission === 'granted' ? (
              <>
                <Bell className="w-3.5 h-3.5 text-emerald-400" />
                <span className="hidden sm:inline">التنبيهات مفعّلة</span>
              </>
            ) : notificationPermission === 'denied' ? (
              <>
                <BellOff className="w-3.5 h-3.5 text-rose-400" />
                <span className="hidden sm:inline">التنبيهات محجوبة</span>
              </>
            ) : (
              <>
                <Bell className="w-3.5 h-3.5 text-slate-950" />
                <span>تفعيل التنبيهات</span>
              </>
            )}
          </button>

          <div className="hidden md:flex items-center gap-2 bg-slate-900/50 border border-slate-850 px-3.5 py-1.5 rounded-xl text-xs text-slate-300">
            <span className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse" />
            <span>خوادم الربط: متصلة بنجاح</span>
          </div>

          <div className="w-1.5 h-1.5 bg-slate-800 rounded-full" />

          {/* Active Logged-In Profile Indicator */}
          <div className="flex items-center gap-2 bg-slate-900/50 border border-slate-850 px-3 py-1.5 rounded-xl">
            <div className="w-8 h-8 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-xs font-bold text-emerald-400 font-mono">
              {currentUser?.role === 'owner' ? 'OWN' : 'SUB'}
            </div>
            <div className="text-right hidden sm:block">
              <span className="text-xs font-bold text-slate-200 block leading-tight">{currentUser?.name}</span>
              <span className="text-[9px] text-slate-500 block leading-none mt-0.5">
                {currentUser?.role === 'owner' ? 'صاحب الوكالة' : 'مشرف المنشأة'}
              </span>
            </div>
            <button 
              onClick={() => {
                localStorage.removeItem('sanad_user');
                setCurrentUser(null);
                setBusinesses([]);
                setBookings([]);
                setComplaints([]);
                setWebhookLogs([]);
                setPaymentRequests([]);
                setTab('dashboard');
              }}
              className="mr-1.5 p-1.5 bg-slate-950 hover:bg-rose-950/30 text-slate-400 hover:text-rose-400 border border-slate-800 hover:border-rose-900/30 rounded-lg text-[9px] font-bold transition-all cursor-pointer"
              title="تسجيل الخروج"
            >
              خروج
            </button>
          </div>
        </div>
      </header>

      {/* Main Container Layout */}
      <div className="flex flex-1 relative items-stretch">

        {/* Sidebar Left Column */}
        <aside className={`fixed inset-y-0 right-0 z-30 w-64 bg-slate-950 border-l border-slate-900/80 p-4 pt-20 lg:pt-4 flex flex-col justify-between transform transition-transform lg:transform-none lg:static ${
          sidebarOpen ? 'translate-x-0' : 'translate-x-full'
        }`}>
          <div className="space-y-6">

            <div className="space-y-1.5">
              <span className="text-[10px] text-slate-500 font-bold tracking-wider uppercase px-3 block">قائمة التشغيل والأتمتة</span>
              <nav className="space-y-1">

                <button
                  onClick={() => { setTab('dashboard'); setSidebarOpen(false); }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    tab === 'dashboard' 
                      ? 'bg-slate-900 text-emerald-400 border border-slate-800 shadow-sm' 
                      : 'text-slate-400 hover:bg-slate-900/50 hover:text-slate-200'
                  }`}
                >
                  <LayoutDashboard className="w-4 h-4 shrink-0" />
                  <span>لوحة التحكم والمؤشرات</span>
                </button>

                <button
                  onClick={() => { setTab('agents'); setSidebarOpen(false); }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    tab === 'agents' 
                      ? 'bg-slate-900 text-emerald-400 border border-slate-800 shadow-sm' 
                      : 'text-slate-400 hover:bg-slate-900/50 hover:text-slate-200'
                  }`}
                >
                  <Settings className="w-4 h-4 shrink-0" />
                  <span>{currentUser?.role === 'owner' ? 'إعدادات الوكلاء والشركات' : 'إعدادات شركتي ومساعد الـ AI'}</span>
                </button>

                <button
                  onClick={() => { setTab('pricing'); setSidebarOpen(false); }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    tab === 'pricing' 
                      ? 'bg-slate-900 text-emerald-400 border border-slate-800 shadow-sm' 
                      : 'text-slate-400 hover:bg-slate-900/50 hover:text-slate-200'
                  }`}
                >
                  <CreditCard className="w-4 h-4 shrink-0" />
                  <span>{currentUser?.role === 'owner' ? 'خطط الأسعار واشتراكات العملاء' : 'اشتراكي وفواتيري 💳'}</span>
                </button>

                <button
                  onClick={() => { setTab('simulator'); setSidebarOpen(false); }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    tab === 'simulator' 
                      ? 'bg-slate-900 text-emerald-400 border border-slate-800 shadow-sm' 
                      : 'text-slate-400 hover:bg-slate-900/50 hover:text-slate-200'
                  }`}
                >
                  <Smartphone className="w-4 h-4 shrink-0" />
                  <span>غرفة التجريب والـ Sandbox</span>
                </button>

              </nav>
            </div>

            <div className="space-y-1.5">
              <span className="text-[10px] text-slate-500 font-bold tracking-wider uppercase px-3 block">سجلات العمليات الآلية</span>
              <nav className="space-y-1">

                <button
                  onClick={() => { setTab('bookings'); setSidebarOpen(false); }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    tab === 'bookings' 
                      ? 'bg-slate-900 text-emerald-400 border border-slate-800 shadow-sm' 
                      : 'text-slate-400 hover:bg-slate-900/50 hover:text-slate-200'
                  }`}
                >
                  <Calendar className="w-4 h-4 shrink-0" />
                  <span>جدول الحجوزات الآلية</span>
                  {bookings.filter(b => b.status === 'pending').length > 0 && (
                    <span className="mr-auto w-4 h-4 bg-amber-500 text-slate-950 font-bold text-[9px] rounded-full flex items-center justify-center font-mono animate-pulse">
                      {bookings.filter(b => b.status === 'pending').length}
                    </span>
                  )}
                </button>

                <button
                  onClick={() => { setTab('complaints'); setSidebarOpen(false); }}
                  className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    tab === 'complaints' 
                      ? 'bg-slate-900 text-emerald-400 border border-slate-800 shadow-sm' 
                      : 'text-slate-400 hover:bg-slate-900/50 hover:text-slate-200'
                  }`}
                >
                  <MessageSquareWarning className="w-4 h-4 shrink-0" />
                  <span>صندوق شكاوى العملاء</span>
                  {complaints.filter(c => c.status !== 'resolved').length > 0 && (
                    <span className="mr-auto w-4 h-4 bg-rose-500 text-white font-bold text-[9px] rounded-full flex items-center justify-center font-mono">
                      {complaints.filter(c => c.status !== 'resolved').length}
                    </span>
                  )}
                </button>

              </nav>
            </div>

            {currentUser?.role === 'owner' && (
              <div className="space-y-1.5">
                <span className="text-[10px] text-slate-500 font-bold tracking-wider uppercase px-3 block">الربط التقني الفعلي</span>
                <nav className="space-y-1">

                  <button
                    onClick={() => { setTab('integration'); setSidebarOpen(false); }}
                    className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                      tab === 'integration' 
                        ? 'bg-slate-900 text-emerald-400 border border-slate-800 shadow-sm' 
                        : 'text-slate-400 hover:bg-slate-900/50 hover:text-slate-200'
                    }`}
                  >
                    <Code2 className="w-4 h-4 shrink-0" />
                    <span>إعدادات ربط الـ APIs</span>
                  </button>

                </nav>
              </div>
            )}

          </div>

          {/* Sidebar Footer info */}
          <div className="pt-4 border-t border-slate-900 space-y-3">
            <div className="p-3 bg-slate-900/40 border border-slate-900 rounded-xl space-y-1.5 text-[11px] text-slate-400 leading-normal">
              <div className="flex items-center gap-1 text-emerald-400 font-bold">
                <Sparkles className="w-3.5 h-3.5" />
                <span>الذكاء الاصطناعي مفعّل</span>
              </div>
              <span>يتم معالجة جميع المراسلات بنموذج Gemini 3.5-Flash الأسرع والأذكى لحفظ المعايير بدقة.</span>
            </div>

            <span className="text-[9px] text-slate-600 block text-center font-mono">
              &copy; Sanad AI Inc. 2026
            </span>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="flex-1 p-4 md:p-6 lg:p-8 overflow-y-auto max-w-7xl mx-auto w-full space-y-6">
          {tab === 'dashboard' && (
            <DashboardOverview 
              bookings={bookings}
              complaints={complaints}
              webhookLogs={webhookLogs}
              onNavigate={(t) => setTab(t)}
              onReset={handleResetData}
              isResetting={isResetting}
            />
          )}

          {tab === 'agents' && (
            <ClientConfigurator 
              businesses={businesses}
              webhookLogs={webhookLogs}
              onUpdateBusiness={handleUpdateBusiness}
            />
          )}

          {tab === 'pricing' && (
            <PricingManager 
              businesses={businesses}
              onUpdateSubscription={handleUpdateSubscription}
              currentUser={currentUser}
              paymentRequests={paymentRequests}
              onRefreshData={fetchState}
            />
          )}

          {tab === 'simulator' && (
            <SandboxSimulator 
              businesses={businesses}
              onTriggerSimulation={handleTriggerSimulation}
              onRefreshData={fetchState}
            />
          )}

          {tab === 'bookings' && (
            <BookingsManager 
              bookings={bookings}
              businesses={businesses}
              onManageBooking={handleManageBooking}
            />
          )}

          {tab === 'complaints' && (
            <ComplaintsDesk 
              complaints={complaints}
              businesses={businesses}
              onManageComplaint={handleManageComplaint}
            />
          )}

          {tab === 'integration' && (
            <IntegrationHub />
          )}
        </main>

      </div>
    </div>
  );
}
